def transform(grid):
    """Extend the rightmost row of each contiguous non-background band."""
    h, w = len(grid), len(grid[0])
    counts = {}
    for row in grid:
        for value in row:
            counts[value] = counts.get(value, 0) + 1
    bg = max(counts, key=counts.get)
    out = [row[:] for row in grid]

    # A band is a maximal run of rows containing any non-background cells.
    r = 0
    while r < h:
        if all(v == bg for v in grid[r]):
            r += 1
            continue
        start = r
        while r < h and any(v != bg for v in grid[r]):
            r += 1
        end = r

        # Within each band, extend only the row(s) reaching the furthest-right
        # foreground cell. This leaves bands already reaching the edge intact.
        right_edges = [max((c for c, v in enumerate(grid[rr]) if v != bg),
                           default=-1) for rr in range(start, end)]
        furthest = max(right_edges)
        for rr, right in zip(range(start, end), right_edges):
            if right == furthest:
                for c in range(right + 1, w):
                    out[rr][c] = 1
    return out

